const DAYS=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const N=3,WINDOW=14;
let data={tasks:[],rules:[]},revs={},today=null;
const $=id=>document.getElementById(id);
function parse(s){const p=s.split('-').map(Number);return new Date(Date.UTC(p[0],p[1]-1,p[2]));}
function fmt(d){return d.toISOString().slice(0,10);}
function addDays(s,n){const d=parse(s);d.setUTCDate(d.getUTCDate()+n);return fmt(d);}
function wd(s){return parse(s).getUTCDay();}
function windowDays(){const a=[];for(let i=0;i<WINDOW;i++)a.push(addDays(today,i));return a;}
function blocked(rules){return new Set(rules.map(r=>r.weekday));}
function label(s){const d=parse(s);return DAYS[d.getUTCDay()]+', '+String(d.getUTCDate()).padStart(2,'0')+'/'+String(d.getUTCMonth()+1).padStart(2,'0');}
function loads(tasks){const m={};for(const t of tasks)for(const d of t.dates||[])m[d]=(m[d]||0)+1;return m;}
function pick(allowed,load,taken,target){let best=null,bs=null;allowed.forEach((d,i)=>{if(taken.has(d))return;const sc=[load[d]||0,Math.abs(i-target)];if(!bs||sc[0]<bs[0]||(sc[0]===bs[0]&&sc[1]<bs[1])){best=d;bs=sc;}});return best;}
async function load(){const r=await tessera.call('data.read',{});data={tasks:r.data.tasks||[],rules:r.data.rules||[]};revs=r.revisions;}
function render(){
const rl=$('rules');rl.textContent='';
for(const r of data.rules){const li=document.createElement('li');li.setAttribute('data-hook','rule');const s=document.createElement('span');s.textContent='Nunca às '+DAYS[r.weekday].toLowerCase()+(r.weekday>0&&r.weekday<6?'s':'s');if(r.weekday===0||r.weekday===6)s.textContent='Nunca aos '+DAYS[r.weekday].toLowerCase()+'s';const b=document.createElement('button');b.type='button';b.className='ghost';b.setAttribute('data-hook','rule-remove');b.textContent='Remover';b.setAttribute('aria-label','Remover bloqueio de '+DAYS[r.weekday]);b.addEventListener('click',()=>removeRule(r.id));li.append(s,b);rl.appendChild(li);}
if(!data.rules.length){const p=document.createElement('li');p.textContent='Nenhum dia bloqueado.';rl.appendChild(p);}
const sel=$('rd');const cur=sel.value;sel.textContent='';const bl=blocked(data.rules);let first=null;
for(let i=0;i<7;i++){const o=document.createElement('option');o.value=String(i);o.textContent=DAYS[i];sel.appendChild(o);if(first===null&&!bl.has(i))first=i;}
sel.value=cur&&!bl.has(Number(cur))?cur:String(first===null?0:first);
const items=[];for(const t of data.tasks)for(const d of t.dates||[])items.push({d,t});
items.sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:a.t.name.localeCompare(b.t.name));
const ul=$('sessions');ul.textContent='';
for(const it of items){const li=document.createElement('li');li.setAttribute('data-hook','session');const tm=document.createElement('time');tm.setAttribute('datetime',it.d);tm.textContent=label(it.d)+' · noite';const n=document.createElement('span');n.className='nm';n.setAttribute('data-hook','session-task');n.textContent=it.t.name;li.append(tm,n);ul.appendChild(li);}
$('empty').hidden=data.tasks.length>0;
}
function say(id,t,ok){const e=$(id);e.textContent=t;e.className=ok?'ok':'err';}
async function addTask(){
const name=$('tn').value.trim();
if(!name){say('msg','Digite o nome do assunto.',false);return;}
const bl=blocked(data.rules);const allowed=windowDays().filter(d=>!bl.has(wd(d)));
if(!allowed.length){say('msg','Todos os dias estão bloqueados. Remova um bloqueio primeiro.',false);return;}
const load_=loads(data.tasks);const taken=new Set();const n=Math.min(N,allowed.length);
for(let k=0;k<n;k++){const target=Math.floor((k+0.5)*allowed.length/n);const d=pick(allowed,load_,taken,target);if(d){taken.add(d);load_[d]=(load_[d]||0)+1;}}
const dates=[...taken].sort();
try{await tessera.call('data.patch',{operations:[{op:'add',collection:'tasks',record:{name,dates}}]});await load();$('tn').value='';render();say('msg','Assunto adicionado em '+dates.length+' noite(s) e salvo.',true);}catch(e){say('msg','Não consegui salvar o assunto. Tente de novo.',false);}
}
async function addRule(){
const w=Number($('rd').value);
if(blocked(data.rules).has(w)){say('rmsg',DAYS[w]+' já está bloqueado.',false);return;}
const rules=data.rules.concat([{weekday:w}]);const bl=blocked(rules);
const allowed=windowDays().filter(d=>!bl.has(wd(d)));
if(!allowed.length){say('rmsg','Não dá para bloquear todos os dias da semana.',false);return;}
const load_=loads(data.tasks);const ops=[{op:'add',collection:'rules',record:{weekday:w}}];
for(const t of data.tasks){const old=t.dates||[];const keep=old.filter(d=>!bl.has(wd(d)));const moved=old.length-keep.length;if(!moved)continue;
const taken=new Set(keep);for(const d of old)if(bl.has(wd(d)))load_[d]=Math.max(0,(load_[d]||1)-1);
for(let k=0;k<moved;k++){const target=Math.floor((k+0.5)*allowed.length/moved);let d=pick(allowed,load_,taken,target);if(d){taken.add(d);load_[d]=(load_[d]||0)+1;}}
if(!taken.size){taken.add(allowed[0]);}
ops.push({op:'replace',collection:'tasks',id:t.id,revisionCount:revs.tasks[t.id],fields:{dates:[...taken].sort()}});}
try{await tessera.call('data.patch',{operations:ops});await load();render();say('rmsg','Bloqueio salvo. As noites de '+DAYS[w].toLowerCase()+' foram remanejadas.',true);}catch(e){say('rmsg','Não consegui salvar o bloqueio. Tente de novo.',false);}
}
async function removeRule(id){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'rules',id,revisionCount:revs.rules[id]}]});await load();render();say('rmsg','Bloqueio removido e salvo. As noites já marcadas continuam como estão.',true);}catch(e){say('rmsg','Não consegui remover o bloqueio.',false);}
}
$('ta').addEventListener('click',addTask);
$('tn').addEventListener('keydown',e=>{if(e.key==='Enter')addTask();});
$('ra').addEventListener('click',addRule);
(async()=>{try{const c=await tessera.call('clock.now',{});today=c.date;await load();render();}catch(e){say('msg','Não consegui abrir o plano.',false);}})();

