ops.push({op:'replace',collection:'tasks',id:t.id,revisionCount:revs.tasks[t.id],fields:{dates:[...taken].sort()}});}
try{await tessera.call('data.patch',{operations:ops});await load();render();say('rmsg','Bloqueio salvo. As noites de '+DAYS[w].toLowerCase()+' foram remanejadas.',true);}catch(e){say('rmsg','Não consegui salvar o bloqueio. Tente de novo.',false);}
}
async function removeRule(id){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'rules',id,revisionCount:revs.rules[id]}]});await load();render();say('rmsg','Bloqueio removido e salvo. As noites já marcadas continuam como estão.',true);}catch(e){say('rmsg','Não consegui remover o bloqueio.',false);}
}
async function addCards(){
const lines=$('cn').value.split('\n').map(l=>l.trim()).filter(Boolean);
const ops=[];let skipped=0;
for(const l of lines){const m=l.match(/^(.+?)\s*(?:::|=|\s-\s|–|—)\s*(.+)$/);if(!m){skipped++;continue;}ops.push({op:'add',collection:'cards',record:{front:m[1].trim(),back:m[2].trim()}});}
if(!ops.length){say('cmsg','Não encontrei cartões. Escreva cada linha como pergunta = resposta.',false);return;}
try{await tessera.call('data.patch',{operations:ops});await load();$('cn').value='';render();say('cmsg',ops.length+' cartão(ões) criado(s) e salvo(s).'+(skipped?' '+skipped+' linha(s) sem "=" foram ignoradas.':''),true);}catch(e){say('cmsg','Não consegui salvar os cartões. Suas anotações continuam no campo.',false);}
}
async function removeCard(id){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'cards',id,revisionCount:revs.cards[id]}]});shown.delete(id);await load();render();say('cmsg','Cartão removido.',true);}catch(e){say('cmsg','Não consegui remover o cartão.',false);}
}
